css:
.ccto-root .cc-ophost{position: relative;height: 300px}
.ccto-root .cc-chart{border-radius: inherit;z-index: 2}
.ccto-root .cc-chart{position: absolute;inset: 0px;display: flex;flex-direction: column;padding: 10px 14px 8px;background: linear-gradient(color-mix(in srgb, var(--wa-point, rgb(14 32 54)) 97%, transparent), color-mix(in srgb, var(--wa-surface, rgb(12 26 46)) 97%, transparent));box-shadow: rgba(42, 124, 160, 0.75) 0px 0px 0px 1px inset;color: var(--wa-point, rgb(199, 236, 244));font: 400 12px / 1.3 Pretendard, system-ui, sans-serif;animation: 0.35s ease 0s 1 normal none running ccChartIn}
.ccto-root .cc-chart .pl,.ccto-root .cc-chart .ct i,.ccto-root .cc-chart .ct b{filter: hue-rotate(var(--cc-chue,0deg))}
.ccto-root .cc-chart .ct{display: flex;align-items: center;gap: 6px;font-weight: 500;font-size: 15px;color: var(--wa-text, rgb(255, 255, 255));white-space: nowrap}
.ccto-root .cc-chart .ct i{display: block;width: 8px;height: 8px;background: var(--wa-point, rgb(42, 124, 160));flex: 0 0 auto}
.ccto-root .cc-chart .ct b{margin-left: auto;font-family: Tomorrow, Pretendard, sans-serif;font-weight: 400;font-size: 18px;color: var(--wa-point, rgb(0, 255, 210))}
.ccto-root .cc-chart .ct b small{font: 400 11px Pretendard, sans-serif;color: var(--wa-text-sub, rgb(142, 166, 179));margin-left: 3px}
.ccto-root .cc-chart .pl{position: relative;flex: 1 1 0%;min-height: 0px;margin-top: 6px}
.ccto-root .cc-chart svg{position: absolute;inset: 0px;width: 100%;height: 100%;overflow: visible}
.ccto-root .cc-chart .arc{transition: stroke-dasharray 0.9s cubic-bezier(0.22, 0.8, 0.24, 1), stroke-dashoffset 0.9s cubic-bezier(0.22, 0.8, 0.24, 1)}
.ccto-root .cc-chart .gv{position: absolute;left: 0px;right: 0px;bottom: 0px;text-align: center;font-family: Tomorrow, Pretendard, sans-serif;font-size: 22px;color: var(--wa-point, rgb(0, 255, 210))}
.ccto-root .cc-chart .gv small{font: 400 12px Pretendard, sans-serif;color: var(--wa-text-sub, rgb(142, 166, 179));margin-left: 2px}
.ccto-root .cc-chart{animation:none!important}
.ccto-root [data-name="Tab Panel/Operation Info"]{position:relative;width:1010px;padding:0}
.ccto-root:not([data-theme="dark"]) .cc-chart{background: var(--wa-bg, rgb(255, 255, 255));box-shadow: rgb(197, 217, 230) 0px 0px 0px 1px inset;color: var(--wa-point, rgb(32, 64, 90))}
.ccto-root:not([data-theme="dark"]) .cc-chart .ct{color: var(--wa-point, rgb(14, 44, 71))}
.ccto-root:not([data-theme="dark"]) .cc-chart .ct b,.ccto-root:not([data-theme="dark"]) .cc-chart .gv{color: var(--wa-point, rgb(0, 120, 106))}
.ccto-root:not([data-theme="dark"]) .cc-chart .ct b small,.ccto-root:not([data-theme="dark"]) .cc-chart .gv small{color: var(--wa-text-sub, rgb(85, 112, 127))}
